#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

int parent[MAXN], rank[MAXN], cycle[MAXN];

void init(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
        cycle[i] = 0;
    }
}

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void unite(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx == ry) return;
    if (rank[rx] < rank[ry]) {
        parent[rx] = ry;
        cycle[ry] |= cycle[rx];
    } else if (rank[rx] > rank[ry]) {
        parent[ry] = rx;
        cycle[rx] |= cycle[ry];
    } else {
        parent[ry] = rx;
        rank[rx]++;
        cycle[rx] |= cycle[ry];
    }
}

