typedef struct {
    int n;
    int *p;
    int *r;
} DSU;

static void dsu_init(DSU *d, int n) {
    d->n = n;
    d->p = (int*)malloc(sizeof(int) * n);
    d->r = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) d->p[i] = i;
}
static int dsu_find(DSU *d, int x) {
    while (d->p[x] != x) {
        d->p[x] = d->p[d->p[x]];
        x = d->p[x];
    }
    return x;
}
static int dsu_unite(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return 0;
    if (d->r[a] < d->r[b]) {
        int t = a; a = b; b = t;
    }
    d->p[b] = a;
    if (d->r[a] == d->r[b]) d->r[a]++;
    return 1;
}

int main(void) {
    int N, M, Q;
    if (scanf("%d %d %d", &N, &M, &Q) != 3) return 0;

    Query *qs = (Query*)malloc(sizeof(Query) * Q);
    for (int i = 0; i < Q; i++) {
        scanf("%d %d %d", &qs[i].a, &qs[i].b, &qs[i].c);
    }

    /*
      Key fact:
      In an undirected graph, between two vertices:
      - exactly one simple path  <=> they are connected and lie in the same 2-edge-connected-tree structure,
        i.e. every edge on the unique route in the bridge-tree is a bridge, so effectively no cycle is usable.
      - two or more simple paths <=> they are in the same 2-edge-connected component after contracting bridges.

      Equivalent constructive view:
      Let relation c=1 mean "must be in the same block" (cycle-rich component),
      and c=0 mean "must be in different blocks but connected by a tree of bridges".

      So:
      1) Merge all pairs with c=1.
      2) Any c=0 inside one merged component is impossible.
      3) Build a graph on merged components using c=0 constraints.
         For every such pair, there must be exactly one simple path, so this component-graph must be a forest,
         and endpoints of every c=0 must be connected. Thus each c=0 edge itself can be used as a bridge;
         the whole graph must be acyclic. Therefore the c=0 constraints on merged components must form a forest
         (no cycle, no duplicate parallel edge between same vertices, because that would already create 2 simple paths).
      If so, construct each merged component as a cycle (or single vertex), and connect them by the forest edges.
      This satisfies all clues.
    */

    DSU dsu;
    dsu_init(&dsu, N);

    for (int i = 0; i < Q; i++) {
        if (qs[i].c == 1) dsu_unite(&dsu, qs[i].a, qs[i].b);
    }

    int *root_id = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) root_id[i] = -1;

    int K = 0;
    for (int i = 0; i < N; i++) {
        int r = dsu_find(&dsu, i);
        if (root_id[r] == -1) root_id[r] = K++;
    }

    int *comp = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) comp[i] = root_id[dsu_find(&dsu, i)];

    DSU forest;
    dsu_init(&forest, K);

    /* To detect duplicate edges between same component pair */
    Edge *edges = (Edge*)malloc(sizeof(Edge) * Q);
    int ecnt = 0;

    for (int i = 0; i < Q; i++) {
        if (qs[i].c == 0) {
            int x = comp[qs[i].a];
            int y = comp[qs[i].b];
            if (x == y) {
                puts("No");
                return 0;
            }
            if (x > y) {
                int t = x; x = y; y = t;
            }

            /* duplicate check */
            for (int j = 0; j < ecnt; j++) {
                if (edges[j].u == x && edges[j].v == y) {
                    puts("No");
                    return 0;
                }
            }
            edges[ecnt].u = x;
            edges[ecnt].v = y;
            ecnt++;

            /* cycle check in component graph */
            if (dsu_find(&forest, x) == dsu_find(&forest, y)) {
                puts("No");
                return 0;
            }
            dsu_unite(&forest, x, y);
        }
    }

    puts("Yes");
    return 0;
}

