public class Main {
    static int[] parent;
    static boolean[] hasCycle;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int N = Integer.parseInt(firstLine[0]);
        int M = Integer.parseInt(firstLine[1]);
        int Q = Integer.parseInt(firstLine[2]);

        parent = new int[N];
        hasCycle = new boolean[N];
        for (int i = 0; i < N; i++) {
            parent[i] = i;
        }

        int[][] clues = new int[Q][3];
        for (int i = 0; i < Q; i++) {
            String[] parts = br.readLine().split(" ");
            clues[i][0] = Integer.parseInt(parts[0]);
            clues[i][1] = Integer.parseInt(parts[1]);
            clues[i][2] = Integer.parseInt(parts[2]);
        }

        // First process all C_i = 0
        for (int[] clue : clues) {
            if (clue[2] == 0) {
                int a = clue[0], b = clue[1];
                int ra = find(a), rb = find(b);
                if (ra == rb) {
                    if (hasCycle[ra]) {
                        System.out.println("No");
                        return;
                    }
                    // Adding edge in same tree creates a cycle
                    hasCycle[ra] = true;
                } else {
                    // Merge, cycle if either has cycle
                    if (hasCycle[ra] || hasCycle[rb]) {
                        hasCycle[ra] = hasCycle[rb] = true;
                    }
                    union(ra, rb);
                }
            }
        }

        // Then process all C_i = 1
        for (int[] clue : clues) {
            if (clue[2] == 1) {
                int a = clue[0], b = clue[1];
                int ra = find(a), rb = find(b);
                if (ra != rb) {
                    System.out.println("No");
                    return;
                }
                if (!hasCycle[ra]) {
                    System.out.println("No");
                    return;
                }
            }
        }

        System.out.println("Yes");
    }

    static int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    static void union(int ra, int rb) {
        if (ra != rb) {
            parent[rb] = ra;
            hasCycle[ra] |= hasCycle[rb];
        }
    }
}

